<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';requireLogin();$y=(int)($_GET['year']??date('Y'));$m=(int)($_GET['month']??date('n'));[$start,$end]=monthBounds($y,$m);$search=trim((string)($_GET['search']??''));$cat=(int)($_GET['category']??0);$payment=$_GET['payment']??'';$type=$_GET['type']??'';$where=['t.user_id=?','t.transaction_date>=?','t.transaction_date<?'];$p=[currentUserId(),$start,$end];
if($search!==''){$where[]='t.description LIKE ?';$p[]='%'.$search.'%';}if($cat>0){$where[]='t.category_id=?';$p[]=$cat;}if(in_array($payment,['cash','debit_card','credit_card'],true)){$where[]='t.payment_method=?';$p[]=$payment;}if(in_array($type,['income','expense'],true)){$where[]='t.type=?';$p[]=$type;}
$s=db()->prepare("SELECT t.transaction_date,t.type,c.name category_name,t.payment_method,t.amount,t.description FROM transactions t JOIN categories c ON c.id=t.category_id WHERE ".implode(' AND ',$where)." ORDER BY t.transaction_date DESC,t.id DESC");$s->execute($p);header('Content-Type:text/csv;charset=utf-8');header('Content-Disposition:attachment; filename="transactions-'.$y.'-'.str_pad((string)$m,2,'0',STR_PAD_LEFT).'.csv"');$o=fopen('php://output','w');fputcsv($o,['Date','Type','Category','Payment Method','Amount','Description']);while($r=$s->fetch())fputcsv($o,[$r['transaction_date'],$r['type'],$r['category_name'],$r['payment_method'],$r['amount'],$r['description']]);fclose($o);exit;
